        return match ($featureId) {
            1  => ['Kondisi Aliran Rezeki Saat Ini', 'Hambatan Energi Rezeki', 'Arah & Potensi Rezeki ke Depan'],
            2  => ['Kondisi Finansial Saat Ini', 'Risiko & Tantangan Investasi', 'Potensi Pertumbuhan Bisnis'],
            3  => ['Energi Momentum Saat Ini', 'Faktor Penghambat Waktu Baik', 'Peluang di Depan'],
