            5  => ['Energi Hubungan Saat Ini', 'Tantangan Terbesar Hubungan', 'Masa Depan Asmara'],
            6  => ['Kondisi Karir & Kantor Saat Ini', 'Dinamika Toksik yang Perlu Diwaspadai', 'Peluang & Arah Karir ke Depan'],
            7  => ['Karakter Dominan Anak Saat Ini', 'Tantangan Pola Asuh Terbesar', 'Potensi Harmoni Orang Tua-Anak'],
            8  => ['Energi Nama Saat Ini', 'Hambatan Tersembunyi dalam Nama', 'Potensi Transformasi Identitas'],
            9  => ['Kondisi Vitalitas Saat Ini', 'Akar Ketidakseimbangan Energi', 'Jalur Pemulihan & Kesehatan'],
            10 => ['Beban Energi yang Sedang Ditanggung', 'Sumber Energi Negatif Terbesar', 'Potensi Pembersihan & Proteksi'],
